-- Seed: the Sensei launch project. Generated by scripts/gen-seed.mjs from seed-items.json.
-- Safe to re-run: does nothing if a project named 'Sensei launch' already exists.

with p as (
  insert into plan.projects (name, target_date, tracks)
  select 'Sensei launch', date '2026-11-01',
         array['Product','Legal','Infra & SEO','Comms','Day 30','Day 60','Day 90']::text[]
  where not exists (select 1 from plan.projects where name = 'Sensei launch')
  returning id
)
insert into plan.items (project_id, track, title, owner, due, status, notes, sort_order)
select p.id, v.track, v.title, v.owner, v.due, v.status, v.notes, v.sort_order
from p, (values
  ('Product', 'Subway design live across app, SEO pages, age gate', 'Claude Code', date '2026-10-27', 'in_progress', 'Branch merged to main; QA on iPhone Safari + Chrome Android outstanding', 0),
  ('Product', 'Scraper clean 5 nights straight + stale-write alert', 'William', date '2026-10-27', 'at_risk', 'Last successful scrape was Oct 4; nightly job not running. Run manually: bash ~/sensei/sensei.sh scrape', 1),
  ('Product', 'Stale-data guard in app (menu-as-of, hide >48h)', 'Claude Code', date '2026-10-27', 'not_started', '', 2),
  ('Product', 'Rebuild all 108 SEO pages, freeze content', 'William', date '2026-10-27', 'not_started', 'Run after scraper confirmed clean', 3),
  ('Product', 'Remove dispensaries with broken/empty menus', 'William', date '2026-10-27', 'not_started', '', 4),
  ('Legal', 'Form entity; move domain, Supabase, GitHub, Zoho under it', 'William', date '2026-10-29', 'not_started', 'LLC now, convert later if needed. Critical path.', 0),
  ('Legal', 'Terms, privacy policy, persisted 21+ age gate', 'William', date '2026-10-29', 'not_started', '', 1),
  ('Legal', 'Not-a-seller disclaimer on every menu page', 'Claude Code', date '2026-10-29', 'not_started', '', 2),
  ('Legal', 'Read OCM advertising/marketing regs (primary text)', 'William', date '2026-10-29', 'not_started', 'Before any brand-facing or sponsored language', 3),
  ('Legal', 'Replace MTA line bullets with original lookalikes', 'Claude Code', date '2026-10-29', 'not_started', 'Trademark exposure not acceptable at public launch', 4),
  ('Infra & SEO', 'Flip public; robots.txt + sitemap submitted to Search Console', 'William', date '2026-10-29', 'not_started', '', 0),
  ('Infra & SEO', 'Canonicals, meta, Organization/LocalBusiness/ItemList schema', 'Claude Code', date '2026-10-29', 'not_started', '', 1),
  ('Infra & SEO', 'PostHog brand-attributed events; Monday report tested', 'William', date '2026-10-29', 'not_started', '', 2),
  ('Infra & SEO', 'Uptime monitor + Supabase backups', 'William', date '2026-10-29', 'not_started', '', 3),
  ('Infra & SEO', 'hello@sensei.nyc forwarding confirmed', 'William', date '2026-10-29', 'not_started', 'Zoho → Gmail', 4),
  ('Comms', 'One-page Sensei sheet with rate-card placeholder', 'William', date '2026-10-30', 'not_started', 'Ink Minimal', 0),
  ('Comms', 'Target list: 10 NY brands + 5 NYC writers/newsletters', 'William', date '2026-10-31', 'not_started', '', 1),
  ('Comms', 'Send sheet; launch post; social handles claimed', 'William', date '2026-11-01', 'not_started', '', 2),
  ('Comms', 'Start ad test (verify network allows cannabis)', 'William', date '2026-11-01', 'at_risk', 'Google/Meta restrict cannabis ads; confirm where prior test ran', 3),
  ('Comms', 'Five brand discovery conversations opened', 'William', date '2026-11-01', 'not_started', 'Learn spend on Weedmaps/Leafly and proof required', 4),
  ('Day 30', 'Scraper off the Mac (residential proxy on VPS)', 'William', date '2026-12-01', 'not_started', 'Single biggest zero-out risk', 0),
  ('Day 30', '80%+ of pages indexed', 'Automation', date '2026-12-01', 'not_started', 'Fail signal: under 50%', 1),
  ('Day 30', 'One return hook shipped (price comparison)', 'Claude Code', date '2026-12-01', 'not_started', '', 2),
  ('Day 30', 'Move personal tables out of Sensei Supabase', 'William', date '2026-12-01', 'not_started', 'Flow (boards, columns, tasks, notes), NearNosh (votes, scores view, vote function), metropole_plans, bill tracker (banc_* tables + ledger schema). Finance tables are empty. Keep plan schema.', 3),
